/* 4 bits per pixel: 0 transparent, 1 paper, 2..15 an ink;
 * value minus 1 rescales to the engine's 0..15 grey level. */
static int ch_at(int id, int x, int y) {
    int i = y * CHESS_TILE + x;
    if (id < 0 || id >= CHESS_COUNT || i < 0 || i >= CHESS_TILE * CHESS_TILE)
        return 0;
    return (ch_px[id][i >> 1] >> ((i & 1) * 4)) & 15;
}
